[ExtensionOf(classStr(GUPBasePriceCalcItem))]
internal final class METGUPBasePriceCalcItem_extension
{
}

Method.Source:
/// <summary>
/// init itemBasePriceCalcTransDetail from VendListPrice to for Custom fields
/// </summary>
/// <param name = "_vendListPriceTmp"></param>
/// <param name = "_priceTermAgreementTmp"></param>
protected void initTransDetailFromVendListPriceAndPriceTerm(GUPVendListPriceTmp _vendListPriceTmp, GUPPriceTermAgreementTmp _priceTermAgreementTmp)
{
    next initTransDetailFromVendListPriceAndPriceTerm(_vendListPriceTmp, _priceTermAgreementTmp);

    //pass VendClaim to itemBasePriceCalcTransDetail
    itemBasePriceCalcTransDetail.METVendClaimEnabled = _vendListPriceTmp.METVendClaimEnabled;
}

/// <summary>
/// set basePriceCalcTrans custom fields
/// </summary>
/// <param name = "_cheapPriceResult"></param>
protected void setItemBasePriceCalcTransData(GUPItemBasePriceCalcTransDetail _cheapPriceResult)
{
    next setItemBasePriceCalcTransData(_cheapPriceResult);

    basePriceCalcTrans.METVendClaimEnabled = _cheapPriceResult.METVendClaimEnabled;
}
